package dev.zomboid.clans;
public final class NexusHud {
 static long until,flash;static int hp,max=100,damage,phase;static String result="";static Object connection;
 public static void accept(String data){String[] row=data.split("\\|",-1);if(row.length!=5)return;Object mc=R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");connection=R.call(mc,"getConnection");hp=Integer.parseInt(row[0]);max=Math.max(1,Integer.parseInt(row[1]));phase=Integer.parseInt(row[3]);result=row[4];until=System.nanoTime()+ (result.isEmpty()?3000000000L:6000000000L);if(Integer.parseInt(row[2])>0){damage=Integer.parseInt(row[2]);flash=System.nanoTime()+2500000000L;}}
 public static void render(Object event){Object mc=R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");long now=System.nanoTime();if(now>=until||R.get(mc,"player")==null||R.call(mc,"getConnection")!=connection||R.yes(R.get(R.get(mc,"options"),"hideGui")))return;Object g=R.call(event,"getGuiGraphics"),font=R.get(mc,"font"),window=R.call(mc,"getWindow");int width=((Number)R.call(window,"getGuiScaledWidth")).intValue(),left=Math.max(4,width/2-110),right=Math.min(width-4,left+220),top=48;boolean hit=now<flash;R.call(g,"fill",left,top,right,top+47,0xc0191d18);R.call(g,"fill",left+5,top+34,right-5,top+42,0xff34342f);R.call(g,"fill",left+5,top+34,left+5+(int)((right-left-10)*Math.max(0,Math.min(1,hp/(double)max))),top+42,hit?0xffcc4035:0xffa4ac63);Object pose=R.call(g,"pose");R.call(pose,"pushPose");R.call(pose,"translate",(float)(left+8),(float)(top+6),0f);R.call(pose,"scale",1.5f,1.5f,1f);R.call(g,"drawString",font,result.isEmpty()?"NEXO  "+hp+" / "+max:result,0,0,hit?0xffff6358:0xffe6ddbd,false);R.call(pose,"popPose");R.call(g,"drawString",font,"FASE "+phase+" / 3"+(hit?"   DAÑO −"+damage+" PV":""),left+8,top+23,hit?0xffff8874:0xffc5c6a9,false);}
}
